functions.copyGridDataToPopUp:
function copyGridDataToPopUp(id, event) {

		var ret = $("#languageSearchGrid").jqGrid('getRowData', id);

		$("#propertyKey1").html(ret.propertyKey);
		$("#defaultValue1").html(ret.defaultValue);
		$("#glanguageValue").html(ret.globalLangValue); 
		$("#createdBy1").html(ret.createdBy);
		$("#createdDate1").html(ret.createdDate);
		$("#updBy1").html(ret.updBy);
		$("#updDate1").html(ret.updDate);

		$("#langValue1").html($("#language option:selected").text());

		if("Y"==ret.localOverride) {
			$("#overrideValue").val(ret.langValue);
			$(".changedTime").show();
		} else {
			$("#overrideValue").val("");
			$(".changedTime").hide();
		}

		$("#editLangId").val(ret.langId);
		$("#editRowId").val(id);
		$("#isMobile").val(ret.isMobile);


		if("1"==ret.langId) {
			$("#languageSpecificValue").hide();
		} else {
			$("#languageSpecificValue").show();
		}

		$("#EditDialog").modal('show').draggable();

		setTimeout(function(){ $("#overrideValue").focus(); }, 500);

		event.preventDefault();
		event.stopPropagation();
		}

functions.callSearch:
function callSearch() {

		$("#languageSearchGrid").jqGrid('setGridParam', {
			datatype : 'json',
			page : 1
		});
		$("#languageSearchGrid").jqGrid('setGridParam', {
			postData : {
				languageId : $("#language").val(),
				propertyType : $("#propertyType").val(),
				propertyKey : $("#propertyKey").val(),
				propertyValue : $("#propertyValue").val(),
				REQ_SEARCH_FLAG : true
			},
			url : "fetchLanguageProperties",
			search : true
		}).trigger('reloadGrid');
	}

functions.resizeGrid:
function resizeGrid(gridId) {

		var gridObj = $("#" + gridId);

		var gridHeight = window.parent.getParentHeight() - 149;
		var gridWidth = $(window).width() - 14;
		if (gridWidth < 270)
			gridWidth = 270;

		try {
			if ($(window).width() < 992) {
				if (oldWidth > 992) {
					gridObj.trigger('reloadGrid');
				}
			} else {
				if (oldWidth < 992) {
					gridObj.trigger('reloadGrid');
				}
			}
		} catch (e) {
		}

		gridObj.jqGrid('setGridWidth', gridWidth);
		gridHeight = gridHeight;
		$("#gbox_" + gridObj[0].id + " .ui-jqgrid-bdiv").css("height",
				gridHeight + "px");
		oldWidth = gridWidth;
	}

functions.clickSave:
function clickSave() {

		if (trimString($("#overrideValue").val()).toUpperCase() == trimString($("#defaultValue1").html()).toUpperCase()) {
			tryFocusBS($("#overrideValue"));
			window.parent.showAlert("Overrided Text is should not be same as Default Text"); 
			return false;
		}

		var retVal = $.ajax({
			url: "EditPropertyValueBS",
			global: false,
			type: "POST",
			data: {
				propertyKey : $("#propertyKey1").html(),
				overrideValue: $("#overrideValue").val(),
				languageId1 : $("#editLangId").val(),
				isMobile : $("#isMobile").val()
			},
			dataType: "json",
			async: false
			}).responseText;
		retVal = jQuery.parseJSON(retVal);

		if(retVal!=null) {
			if(retVal.jsonMessage==null) {
				if(retVal.langPropertyMap!=null) {
					var gridObj = $('#languageSearchGrid');
					var index =gridObj.jqGrid('getInd', $("#editRowId").val());
					var position = 'first';
					var srcRowId='';
				    if ( index == 1 ) {
						position = 'first';
					} else {
				    	position = 'after';
				        srcRowId = gridObj.find('tr#' + $("#editRowId").val()).prev()[0].id;
				    }

				    gridObj.jqGrid('delRowData', $("#editRowId").val());
				    gridObj.jqGrid('addRowData', $("#editRowId").val(), retVal.langPropertyMap[0], position, srcRowId);
//					$('#languageSearchGrid').jqGrid('setRowData', $("#editRowId").val(), retVal.langPropertyMap[0]);
				}

				$("#EditDialog").modal('hide')

				window.parent.showAlert(retVal.langDTO.createDateText); 
				return false;
			} else {
				window.parent.showAlert(retVal.jsonMessage); 
				return false;
			}
		}


	}

